/*
 * Bengaluru Atlas service worker.
 *
 * Generated by vite.config.ts at build time. The shell is precached; map
 * tiles, Commons photographs and the live APIs are cached opportunistically
 * so the last city you looked at survives a dead signal.
 */

const VERSION = "mww0b6j2";
const PRECACHE = [
  "./index.html",
  "./site.webmanifest",
  "./offline.html",
  "./favicon.svg",
  "./favicon.ico",
  "./icon-192.png",
  "./icon-512.png",
  "./icon-maskable-512.png",
  "./apple-touch-icon.png",
  "./data/atlas.json",
  "./data/traffic.json",
  "./map/light.json",
  "./map/dark.json",
  "./assets/fraunces-0vNsIEPK.woff2",
  "./assets/jetbrains-mono-BdOwYlYc.woff2",
  "./assets/manrope-ubYmXSK8.woff2",
  "./assets/index-Dy1lY2BK.css",
  "./assets/index-B1KVf8e9.js"
];

const SCOPE = self.registration.scope;
const STATIC_CACHE = `atlas-static-${VERSION}`;
const RUNTIME_CACHE = 'atlas-runtime-v1';
const TILE_CACHE = 'atlas-tiles-v1';
const IMAGE_CACHE = 'atlas-images-v1';
const MAX_RUNTIME = 80;
const MAX_TILES = 360;
const MAX_IMAGES = 90;

const absolute = (path) => new URL(path, SCOPE).href;
const INDEX = absolute('./index.html');
const OFFLINE = absolute('./offline.html');

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(STATIC_CACHE);
      await Promise.all(
        PRECACHE.map((path) =>
          cache
            .add(new Request(absolute(path), { cache: 'reload' }))
            .catch(() => undefined),
        ),
      );
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key.startsWith('atlas-static-') && key !== STATIC_CACHE)
          .map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

async function trim(cacheName, max) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length <= max) return;
  await Promise.all(
    keys.slice(0, keys.length - max).map((key) => cache.delete(key)),
  );
}

async function cacheFirst(request, cacheName, max) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok || response.type === 'opaque') {
    await cache.put(request, response.clone());
    await trim(cacheName, max);
  }
  return response;
}

async function staleWhileRevalidate(event, request, cacheName, max) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  const update = fetch(request)
    .then(async (response) => {
      if (response.ok || response.type === 'opaque') {
        await cache.put(request, response.clone());
        await trim(cacheName, max);
      }
      return response;
    })
    .catch(() => null);

  if (cached) {
    event.waitUntil(update);
    return cached;
  }

  const fresh = await update;
  return fresh || Response.error();
}

async function navigationResponse(event) {
  try {
    return await fetch(event.request);
  } catch {
    return (
      (await caches.match(INDEX)) ||
      (await caches.match(OFFLINE)) ||
      Response.error()
    );
  }
}

async function sameOriginResponse(request, url) {
  if (
    url.pathname.endsWith('/data/atlas.json') ||
    url.pathname.endsWith('/data/traffic.json') ||
    url.pathname.endsWith('/map/light.json') ||
    url.pathname.endsWith('/map/dark.json')
  ) {
    return cacheFirst(request, STATIC_CACHE, Infinity);
  }

  const cached = await caches.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(RUNTIME_CACHE);
    await cache.put(request, response.clone());
    await trim(RUNTIME_CACHE, MAX_RUNTIME);
  }
  return response;
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  if (request.headers.has('range')) return;

  const url = new URL(request.url);

  if (request.mode === 'navigate') {
    event.respondWith(navigationResponse(event));
    return;
  }

  if (url.origin === self.location.origin) {
    event.respondWith(sameOriginResponse(request, url));
    return;
  }

  if (url.hostname.endsWith('openfreemap.org')) {
    event.respondWith(staleWhileRevalidate(event, request, TILE_CACHE, MAX_TILES));
    return;
  }

  if (url.hostname.endsWith('wikimedia.org')) {
    event.respondWith(cacheFirst(request, IMAGE_CACHE, MAX_IMAGES));
    return;
  }

  if (
    url.hostname === 'api.open-meteo.com' ||
    url.hostname === 'api.github.com'
  ) {
    event.respondWith(
      staleWhileRevalidate(event, request, RUNTIME_CACHE, MAX_RUNTIME),
    );
  }
});
